SELECT DISTINCTROW [QImmissione Generale].Commessa, [QImmissione Generale].[Commessa di taglio], [QImmissione Generale].[Record numero], [QImmissione Generale].[Reclamo numero], [QImmissione Generale].[Numero risposta], [QImmissione Generale].Data, [QImmissione Generale].[Famiglia dei prodotti], [QImmissione Generale].[Kg reclamati], [QImmissione Generale].Motivazioni, [QImmissione Generale].Difetto, [QImmissione Generale].[Data risposta], [QImmissione Generale].Soluzione, [QImmissione Generale].Contabilità, [QImmissione Generale].Risposta, [QImmissione Generale].Commento, [QImmissione Generale].[Kg resi], [QImmissione Generale].Esterno, [QImmissione Generale].[Nota di credito], [QImmissione Generale].Accredito, [QImmissione Generale].Rete, [QImmissione Generale].Cliente, [QImmissione Generale].[Codice cliente], [QImmissione Generale].Prodotto, [QImmissione Generale].[Codice articolo], [QImmissione Generale].Spessore, [QImmissione Generale].Dimensioni, [QImmissione Generale].Finitura, [QImmissione Generale].[Kg forniti], [QImmissione Generale].Stabilimento, [QImmissione Generale].Calandra, [QImmissione Generale].[Data calandra], [QImmissione Generale].Bobinatrice, [QImmissione Generale].[Data produzione], [QImmissione Generale].[Numero d'ordine]
FROM [QImmissione Generale]
WHERE (([QImmissione Generale].Commessa In (SELECT [Commessa] FROM [QImmissione Generale] As Tmp GROUP BY [Commessa],[Commessa di taglio] HAVING Count(*)>1  And [Commessa di taglio] = [QImmissione Generale].[Commessa di taglio])))
ORDER BY [QImmissione Generale].Commessa, [QImmissione Generale].[Commessa di taglio];
